class Bag {
  Set<int> ids = {1, 2, 3};

  int size() {
    return this.ids.length;
  }
}

int run() {
  var s = {1, 2, 2, 3};
  var empty = <int>{};

  empty.add(9);
  s.add(3);
  s.add(4);
  s.remove(1);

  var total = 0;
  for (var e in s) {
    total = total + e;
  }

  var bag = Bag();

  return s.length + total + empty.length + bag.size();
}

bool contains() {
  Set<String> names = {'a', 'b'};
  return names.contains('b') && !names.contains('c') && names.isNotEmpty;
}

int mapIsStillAMap() {
  var m = {'a': 1};
  var em = {};
  return m['a'] + em.length;
}
